    Bug 1919751 - Only fetch in-app notification updates on initialization if cache is too old. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D222776

diff --git a/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs b/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
index 9ba45980ced..bd65895b45d 100644
--- a/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
+++ b/mail/components/inappnotifications/modules/InAppNotifications.sys.mjs
@@ -61,7 +61,9 @@ export const InAppNotifications = {
     lazy.NotificationUpdater.onUpdate = updatedNotifications => {
       this.updateNotifications(updatedNotifications);
     };
-    const shouldPopulateFromStorage = await lazy.NotificationUpdater.init();
+    const shouldPopulateFromStorage = await lazy.NotificationUpdater.init(
+      this._jsonFile.data.lastUpdate || 0
+    );
     if (shouldPopulateFromStorage) {
       this._updateNotificationManager();
     }
diff --git a/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs b/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
index 41f189f9ec1..953001256aa 100644
--- a/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
+++ b/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
@@ -59,10 +59,11 @@ export const NotificationUpdater = {
    * Initialize the updater, setting up a scheduled update as well as
    * immediately checking for the latest data from the server.
    *
+   * @param {number} lastUpdate - Timestamp (in ms) of the last cached update.
    * @returns {boolean} True if the caller should initialize its state from
    *   cache, since updating from the network did not yield any information.
    */
-  async init() {
+  async init(lastUpdate) {
     if (this._interval) {
       return false;
     }
@@ -73,6 +74,10 @@ export const NotificationUpdater = {
     this._interval = lazy.setInterval(() => {
       this._fetch();
     }, refreshInterval);
+    // Don't immediately update if the cache is new enough.
+    if (lastUpdate + refreshInterval > Date.now()) {
+      return true;
+    }
     const didFetch = await this._fetch();
     return !didFetch;
   },
diff --git a/mail/components/inappnotifications/test/unit/test_notification_updater.js b/mail/components/inappnotifications/test/unit/test_notification_updater.js
index 05fa55f66b9..ebae351613f 100644
--- a/mail/components/inappnotifications/test/unit/test_notification_updater.js
+++ b/mail/components/inappnotifications/test/unit/test_notification_updater.js
@@ -209,7 +209,7 @@ add_task(async function test_init() {
   const { resolve, promise } = Promise.withResolvers();

   const initTs = Date.now();
-  const initResult = await NotificationUpdater.init();
+  const initResult = await NotificationUpdater.init(0);

   Assert.ok(!initResult, "Should report successful fetch on init");
   Assert.equal(updateSpy.callCount, 1, "Should call update callback in init");
@@ -218,7 +218,7 @@ add_task(async function test_init() {
     "Should pass notifications to update callback from init"
   );

-  const initAgainResult = await NotificationUpdater.init();
+  const initAgainResult = await NotificationUpdater.init(0);

   Assert.ok(
     !initAgainResult,
@@ -235,6 +235,7 @@ add_task(async function test_init() {
   const now = Date.now();

   clearInterval(NotificationUpdater._interval);
+  NotificationUpdater._interval = null;

   Assert.equal(
     NotificationUpdater.onUpdate.callCount,
@@ -253,4 +254,22 @@ add_task(async function test_init() {

   Services.prefs.clearUserPref("mail.inappnotifications.refreshInterval");
   NotificationUpdater.onUpdate = updateSpy;
+  updateSpy.resetHistory();
+});
+
+add_task(async function test_init_withRecentUpdate() {
+  const initTs = Date.now();
+  const initResult = await NotificationUpdater.init(initTs - 100);
+
+  clearInterval(NotificationUpdater._interval);
+  NotificationUpdater._interval = null;
+
+  Assert.ok(initResult, "Should not have fetched updates on init");
+  Assert.equal(
+    updateSpy.callCount,
+    0,
+    "Should not have called the update callback"
+  );
+
+  updateSpy.resetHistory();
 });
